import os
import json
import subprocess
from datetime import datetime, timezone
from dataclasses import dataclass, asdict
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('ticketing-ops')
SEATMAP_SCRIPT = os.environ.get('SEATMAP_SCRIPT', '/opt/ticketing/bin/rebuild_seatmap.py')
PYTHON_BIN = os.environ.get('TICKETING_PYTHON', '/opt/ticketing/venv/bin/python')
ALLOWED_CONFIGS = {'standard', 'in-the-round', 'general-admission', 'theater'}
STATE_DIR = os.environ.get('SEATMAP_STATE_DIR', '/var/lib/ticketing/seatmap_state')

@dataclass
class SeatMapRebuildResult:
    event_id: str
    venue_config: str
    exit_code: int
    succeeded: bool
    stdout_tail: str
    stderr_tail: str
    timed_out: bool = False

def _tail(text: str, lines: int=20) -> str:
    return '\n'.join((text or '').strip().splitlines()[-lines:])

@mcp.tool()
def run_seat_map_rebuild(event_id: str, venue_config: str='standard', timeout_seconds: int=300) -> dict:
    if not event_id or not event_id.replace('-', '').isalnum():
        raise ValueError('event_id must be alphanumeric')
    if venue_config not in ALLOWED_CONFIGS:
        raise ValueError(f'venue_config must be one of {sorted(ALLOWED_CONFIGS)}')
    timeout_seconds = max(10, min(int(timeout_seconds), 1800))
    # Record the most recent rebuild request for this event
    os.makedirs(STATE_DIR, exist_ok=True)
    marker_path = os.path.join(STATE_DIR, f'{event_id}.last_rebuild.json')
    with open(marker_path, 'w', encoding='utf-8') as fh:
        json.dump({
            'event_id': event_id,
            'venue_config': venue_config,
            'timeout_seconds': timeout_seconds,
            'requested_at': datetime.now(timezone.utc).isoformat(),
        }, fh)
    cmd = [PYTHON_BIN, SEATMAP_SCRIPT, '--event', event_id, '--config', venue_config]
    try:
        proc = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_seconds, check=False)
    except subprocess.TimeoutExpired as exc:
        result = SeatMapRebuildResult(event_id=event_id, venue_config=venue_config, exit_code=-1, succeeded=False, stdout_tail=_tail(exc.stdout if isinstance(exc.stdout, str) else ''), stderr_tail=_tail(exc.stderr if isinstance(exc.stderr, str) else ''), timed_out=True)
        return asdict(result)
    result = SeatMapRebuildResult(event_id=event_id, venue_config=venue_config, exit_code=proc.returncode, succeeded=proc.returncode == 0, stdout_tail=_tail(proc.stdout), stderr_tail=_tail(proc.stderr))
    return asdict(result)
